import{_ as t,a0 as c,w as s,s as a,ao as r,I as i,x as o,a1 as p,A as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const g=JSON.parse('{"title":"有用的 Bash 快捷鍵清單 | LCTT x X-CMD","titleTemplate":false,"description":"有用的 Bash 快捷鍵清單 | LCTT (201803) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"有用的 Bash 快捷鍵清單 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"有用的 Bash 快捷鍵清單 | LCTT (201803) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201803/20180217 The List Of Useful Bash Keyboard Shortcuts","title":"有用的 Bash 快捷鍵清單","tag":"201803","desc":""},"relativePath":"201803/20180217 The List Of Useful Bash Keyboard Shortcuts.md","filePath":"[post].md"}'),T={name:"201803/20180217 The List Of Useful Bash Keyboard Shortcuts.md"};function n(L,e,C,h,R,u){const d=c("Link");return s(),a("div",null,[e[13]||(e[13]=r('<h1 id="有用的-bash-快捷鍵清單" tabindex="-1">有用的 Bash 快捷鍵清單 <a class="header-anchor" href="#有用的-bash-快捷鍵清單" aria-label="Permalink to “有用的 Bash 快捷鍵清單”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/02/Bash-720x340.jpg" alt=""></p><p>現如今，我在終端上花的時間更多，嘗試在命令列完成比在圖形界面更多的工作。隨着時間推移，我學了許多 BASH 的技巧。這是一份每個 Linux 用户都應該知道的 BASH 快捷鍵，這樣在終端做事就會快很多。我不會説這是一份完全的 BASH 快捷鍵清單，但是這足夠讓你的 BASH shell 操作比以前更快了。學習更快地使用 BASH 不僅節省了更多時間，也讓你因為學到了有用的知識而感到自豪。那麼，讓我們開始吧。</p><h3 id="alt-快捷鍵" tabindex="-1">ALT 快捷鍵 <a class="header-anchor" href="#alt-快捷鍵" aria-label="Permalink to “ALT 快捷鍵”">​</a></h3><ol><li><p><code>ALT+A</code> – 光標移動到行首。</p></li><li><p><code>ALT+B</code> – 光標移動到所在單詞詞首。</p></li><li><p><code>ALT+C</code> – 終止正在運行的命令/進程。與 <code>CTRL+C</code> 相同。</p></li><li><p><code>ALT+D</code> – 關閉空的終端（也就是它會關閉沒有輸入的終端）。也刪除光標後的全部字符。</p></li><li><p><code>ALT+F</code> – 移動到光標所在單詞詞末。</p></li><li><p><code>ALT+T</code> – 交換最後兩個單詞。</p></li><li><p><code>ALT+U</code> – 將單詞內光標後的字母轉為大寫。</p></li><li><p><code>ALT+L</code> – 將單詞內光標後的字母轉為小寫。</p></li><li><p><code>ALT+R</code> – 撤銷對從歷史記錄中帶來的命令的修改。</p><p>正如你在上面輸出所見，我使用反向搜索拉取了一個指令，並更改了那個指令的最後一個字母，並使用 <code>ALT+R</code> 撤銷了更改。</p></li><li><p><code>ALT+.</code> （注意末尾的點號） – 使用上一條命令的最後一個單詞。</p></li></ol><p>如果你想要對多個命令進行相同的操作的話，你可以使用這個快捷鍵來獲取前幾個指令的最後一個單詞。例如，我需要使用 <code>ls -r</code> 命令輸出以文件名逆序排列的目錄內容。同時，我也想使用 <code>uname -r</code> 命令來查看我的內核版本。在這兩個命令中，相同的單詞是 <code>-r</code> 。這就是需要 <code>ALT+.</code> 的地方。快捷鍵很順手。首先運行 <code>ls -r</code> 來按文件名逆序輸出，然後在其他命令，比如 <code>uname</code> 中使用最後一個單詞 <code>-r</code> 。</p><h3 id="ctrl-快捷鍵" tabindex="-1">CTRL 快捷鍵 <a class="header-anchor" href="#ctrl-快捷鍵" aria-label="Permalink to “CTRL 快捷鍵”">​</a></h3><ol><li><p><code>CTRL+A</code> – 快速移動到行首。</p><p>我們假設你輸入了像下面這樣的命令。當你在第 N 行時，你發現在行首字符有一個輸入錯誤</p></li></ol><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gind . -mtime -1 -type</span></span></code></pre></div><pre><code>注意到了嗎？上面的命令中我輸入了 `gind` 而不是 `find` 。你可以通過一直按着左箭頭鍵定位到第一個字母然後用 `g` 替換 `f` 。或者，僅通過  `CTRL+A` 或 `HOME` 鍵來立刻定位到行首，並替換拼錯的單詞。這將節省你幾秒鐘的時間。\n</code></pre><ol start="2"><li><p><code>CTRL+B</code> – 光標向前移動一個字符。</p><p>這個快捷鍵可以使光標向前移動一個字符，即光標前的一個字符。或者，你可以使用左箭頭鍵來向前移動一個字符。</p></li><li><p><code>CTRL+C</code> – 停止當前運行的命令。</p><p>如果一個命令運行時間過久，或者你誤運行了，你可以通過使用 <code>CTRL+C</code> 來強制停止或退出。</p></li><li><p><code>CTRL+D</code> – 刪除光標後的一個字符。</p><p>如果你的系統退格鍵無法工作的話，你可以使用 <code>CTRL+D</code> 來刪除光標後的一個字符。這個快捷鍵也可以讓你退出當前會話，和 exit 類似。</p></li><li><p><code>CTRL+E</code> – 移動到行末。</p><p>當你修正了行首拼寫錯誤的單詞，按下 <code>CTRL+E</code> 來快速移動到行末。或者，你也可以使用你鍵盤上的 <code>END</code> 鍵。</p></li><li><p><code>CTRL+F</code> – 光標向後移動一個字符。</p><p>如果你想將光標向後移動一個字符的話，按 <code>CTRL+F</code> 來替代右箭頭鍵。</p></li><li><p><code>CTRL+G</code> – 退出歷史搜索模式，不運行命令。</p><p>正如你在上面的截圖看到的，我進行了反向搜索，但是我執行命令，並退出了歷史搜索模式。</p></li><li><p><code>CTRL+H</code> – 刪除光標籤的一個字符，和退格鍵相同。</p></li><li><p><code>CTRL+J</code> – 和 ENTER/RETURN 鍵相同。</p><p>回車鍵不工作？沒問題！ <code>CTRL+J</code> 或 <code>CTRL+M</code> 可以用來替換回車鍵。</p></li><li><p><code>CTRL+K</code> – 刪除光標後的所有字符。</p><p>你不必一直按着刪除鍵來刪除光標後的字符。只要按 <code>CTRL+K</code> 就能刪除光標後的所有字符。</p></li><li><p><code>CTRL+L</code> – 清空屏幕並重新顯示當前行。</p><p>別輸入 <code>clear</code> 來清空屏幕了。只需按 <code>CTRL+M</code> 即可清空並重新顯示當前行。</p></li><li><p><code>CTRL+M</code> – 和 <code>CTRL+J</code> 或 RETURN鍵相同。</p></li><li><p><code>CTRL+N</code> – 在命令歷史中顯示下一行。</p><p>你也可以使用下箭頭鍵。</p></li><li><p><code>CTRL+O</code> – 運行你使用反向搜索時發現的命令，即 CTRL+R。</p></li><li><p><code>CTRL+P</code> – 顯示命令歷史的上一條命令。</p><p>你也可以使用上箭頭鍵。</p></li><li><p><code>CTRL+R</code> – 向後搜索歷史記錄（反向搜索）。</p></li><li><p><code>CTRL+S</code> – 向前搜索歷史記錄。</p></li><li><p><code>CTRL+T</code> – 交換最後兩個字符。</p><p>這是我最喜歡的一個快捷鍵。假設你輸入了 <code>sl</code> 而不是 <code>ls</code> 。沒問題！這個快捷鍵會像下面這張截圖一樣交換字符。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/02/CTRLT-1.gif" alt=""></p></li><li><p><code>CTRL+U</code> – 刪除光標前的所有字符（從光標後的點刪除到行首）。</p><p>這個快捷鍵立刻刪除前面的所有字符。</p></li><li><p><code>CTRL+V</code> – 逐字顯示輸入的下一個字符。</p></li><li><p><code>CTRL+W</code> – 刪除光標前的一個單詞。</p><p>不要和 CTRL+U 弄混了。CTRL+W 不會刪除光標前的所有東西，而是隻刪除一個單詞。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/02/CTRLW-1.gif" alt=""></p></li><li><p><code>CTRL+X</code> – 列出當前單詞可能的文件名補全。</p></li><li><p><code>CTRL+XX</code> – 移動到行首位置（再移動回來）。</p></li><li><p><code>CTRL+Y</code> – 恢復你上一個刪除或剪切的條目。</p><p>記得嗎，我們在第 21 個命令用 <code>CTRL+W</code> 刪除了單詞“-al”。你可以使用 <code>CTRL+Y</code> 立刻恢復。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/02/CTRLY-1.gif" alt=""></p><p>看見了吧？我沒有輸入“-al”。取而代之，我按了 <code>CTRL+Y</code> 來恢復它。</p></li><li><p><code>CTRL+Z</code> – 停止當前的命令。</p><p>你也許很瞭解這個快捷鍵。它終止了當前運行的命令。你可以在前台使用 <code>fg</code> 或在後台使用 <code>bg</code> 來恢復它。</p></li><li><p><code>CTRL+[</code> – 和 <code>ESC</code> 鍵等同。</p></li></ol><h3 id="雜項" tabindex="-1">雜項 <a class="header-anchor" href="#雜項" aria-label="Permalink to “雜項”">​</a></h3><ol><li><p><code>!!</code> – 重複上一個命令。</p></li><li><p><code>ESC+t</code> – 交換最後兩個單詞。</p></li></ol><p>這就是我所能想到的了。將來我遇到 Bash 快捷鍵時我會持續添加的。如果你覺得文章有錯的話，請在下方的評論區留言。我會盡快更新。</p><p>Cheers!</p><hr>',16)),i("p",null,[e[1]||(e[1]=o("via: ",-1)),p(d,{href:"https://www.ostechnix.com/list-useful-bash-keyboard-shortcuts/"},{default:l(()=>[...e[0]||(e[0]=[o("https://www.ostechnix.com/list-useful-bash-keyboard-shortcuts/",-1)])]),_:1})]),i("p",null,[e[5]||(e[5]=o("作者：",-1)),p(d,{href:"https://www.ostechnix.com/author/sk/"},{default:l(()=>[...e[2]||(e[2]=[o("SK",-1)])]),_:1}),e[6]||(e[6]=o(" 譯者：",-1)),p(d,{href:"https://github.com/heart4lor"},{default:l(()=>[...e[3]||(e[3]=[o("heart4lor",-1)])]),_:1}),e[7]||(e[7]=o(" 校對：",-1)),p(d,{href:"https://github.com/wxy"},{default:l(()=>[...e[4]||(e[4]=[o("wxy",-1)])]),_:1})]),i("p",null,[e[10]||(e[10]=o("本文由 ",-1)),p(d,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...e[8]||(e[8]=[o("LCTT",-1)])]),_:1}),e[11]||(e[11]=o(" 原創編譯，",-1)),p(d,{href:"https://linux.cn/"},{default:l(()=>[...e[9]||(e[9]=[o("Linux中國",-1)])]),_:1}),e[12]||(e[12]=o(" 榮譽推出",-1))])])}const b=t(T,[["render",n]]);export{g as __pageData,b as default};
